-- QA COPY of infra/bigquery/293_mk_market_cohorts.sql, generated by name mapping only
-- (mart.market_* -> mart_qa.mk_market_*, ref.client_markets / ref.naming_rules -> mart_qa.mk_*,
-- stg_customer_orders / stg_shoptet_orders -> mart_qa.mm1_* of migration 284). Do not edit by hand.

-- =============================================================================
-- 293_mk_market_cohorts.sql
-- Markets page (v1a, F2): monthly acquisition cohorts per client x first-order
-- market, read at fixed ages (30 / 60 / 90 / 180 / 365 days).
-- Contract: docs/sessions/2026-10-15/markets/CONTRACT.md (mart_qa.mk_market_cohorts).
--
-- Creates
--   mart.sp_refresh_market_cohorts()   rebuilds mart.market_cohorts
--   mart.market_cohorts                snapshot table (CALL at the end)
--
-- Definitions (audit A3, SPEC 3.6)
--   Cohort: customers whose first kept order (mart.market_orders.is_new_customer)
--     falls in cohort_month; market = first_order_market, frozen.
--   Age N: orders dated first_order_date .. first_order_date + N - 1
--     (day 0 = first order), cumulative.
--   Read only once mature: every *_N column is NULL until the LAST customer
--     of the cohort is N days old, i.e. until
--     last day of cohort_month + N - 1 <= as_of_date. as_of_date = the last
--     complete day: yesterday, capped at the client's latest order date, so a
--     stalled feed never makes a cohort look older than its data.
--   repeat_customers_N: customers with 2+ orders within N days.
--   revenue_N: net revenue (base currency, ex VAT) of all cohort customers.
--   gp_N, first_order_gp: product GP (net sales - COGS) summed over
--     costed_customers only = customers whose every order within 365 days is
--     costed. GP per customer = gp_N / costed_customers (NOT / customers).
--     NULL when no customer is costed (RawBark).
--   cohort_spend: paid spend of the market inside the cohort month (all
--     platforms and allocations of mart.market_spend_daily; UNALLOCATED is
--     not in any market). NULL when the client has no spend row that month
--     (before the ad history starts, I7). A month only partly covered (Dobias
--     April 2026 from the 20th) is understated: cohort CAC = cohort_spend /
--     customers is then a lower bound.
--
-- Additive columns beyond CONTRACT.md (flagged in DATA-BUILD.md):
--   costed_customers, first_order_revenue, as_of_date.
--
-- Depends on 290, 291. Refresh: mart.sp_refresh_markets() (294).
-- QA copy: infra/bigquery/qa/293_mk_market_cohorts_qa.sql.
-- =============================================================================

CREATE OR REPLACE PROCEDURE `oneeighty-warehouse.mart_qa.mk_sp_refresh_market_cohorts`()
OPTIONS (description = 'Rebuilds mart.market_cohorts (client x first-order market x cohort month: customers, repeat customers, cumulative revenue and GP at 30/60/90/180/365 days, NULL until mature, cohort-month spend, first-order GP) from mart.market_orders and mart.market_spend_daily. Checks: rows > 0, unique key, customers equal the new customers of market_orders. Migration 293. Called by mart.sp_refresh_markets (294).')
BEGIN
  DECLARE new_rows INT64;
  DECLARE dup_rows INT64;
  DECLARE cust_gap INT64;

  SET @@query_label = 'feature:markets-refresh';

  CREATE OR REPLACE TABLE `oneeighty-warehouse.mart_qa.mk_market_cohorts__next`
  CLUSTER BY client_id, first_order_market, cohort_month
  OPTIONS (description = 'Staging copy for mart.sp_refresh_market_cohorts. Not for reading.')
  AS
  WITH
  as_of AS (
    SELECT client_id,
      LEAST(DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY), MAX(order_date)) AS as_of_date
    FROM `oneeighty-warehouse.mart_qa.mk_market_orders`
    GROUP BY client_id
  ),
  firsts AS (
    SELECT client_id, customer_key, first_order_market, first_order_date,
      net_revenue AS first_revenue, gross_profit AS first_gp
    FROM `oneeighty-warehouse.mart_qa.mk_market_orders`
    WHERE is_new_customer
  ),
  per_cust AS (
    SELECT
      f.client_id, f.first_order_market,
      DATE_TRUNC(f.first_order_date, MONTH) AS cohort_month,
      f.customer_key, f.first_revenue, f.first_gp,
      LOGICAL_AND(IF(o.order_date < DATE_ADD(f.first_order_date, INTERVAL 365 DAY),
                     o.gross_profit IS NOT NULL, TRUE)) AS costed,
      COUNTIF(o.order_date < DATE_ADD(f.first_order_date, INTERVAL 30 DAY))  AS n_30,
      COUNTIF(o.order_date < DATE_ADD(f.first_order_date, INTERVAL 60 DAY))  AS n_60,
      COUNTIF(o.order_date < DATE_ADD(f.first_order_date, INTERVAL 90 DAY))  AS n_90,
      COUNTIF(o.order_date < DATE_ADD(f.first_order_date, INTERVAL 180 DAY)) AS n_180,
      COUNTIF(o.order_date < DATE_ADD(f.first_order_date, INTERVAL 365 DAY)) AS n_365,
      SUM(IF(o.order_date < DATE_ADD(f.first_order_date, INTERVAL 30 DAY),  o.net_revenue, 0)) AS rev_30,
      SUM(IF(o.order_date < DATE_ADD(f.first_order_date, INTERVAL 60 DAY),  o.net_revenue, 0)) AS rev_60,
      SUM(IF(o.order_date < DATE_ADD(f.first_order_date, INTERVAL 90 DAY),  o.net_revenue, 0)) AS rev_90,
      SUM(IF(o.order_date < DATE_ADD(f.first_order_date, INTERVAL 180 DAY), o.net_revenue, 0)) AS rev_180,
      SUM(IF(o.order_date < DATE_ADD(f.first_order_date, INTERVAL 365 DAY), o.net_revenue, 0)) AS rev_365,
      SUM(IF(o.order_date < DATE_ADD(f.first_order_date, INTERVAL 30 DAY),  o.gross_profit, 0)) AS gp_30,
      SUM(IF(o.order_date < DATE_ADD(f.first_order_date, INTERVAL 60 DAY),  o.gross_profit, 0)) AS gp_60,
      SUM(IF(o.order_date < DATE_ADD(f.first_order_date, INTERVAL 90 DAY),  o.gross_profit, 0)) AS gp_90,
      SUM(IF(o.order_date < DATE_ADD(f.first_order_date, INTERVAL 180 DAY), o.gross_profit, 0)) AS gp_180,
      SUM(IF(o.order_date < DATE_ADD(f.first_order_date, INTERVAL 365 DAY), o.gross_profit, 0)) AS gp_365
    FROM firsts f
    JOIN `oneeighty-warehouse.mart_qa.mk_market_orders` o
      ON o.client_id = f.client_id AND o.customer_key = f.customer_key
    GROUP BY f.client_id, f.first_order_market, cohort_month, f.customer_key,
             f.first_revenue, f.first_gp
  ),
  coh AS (
    SELECT
      client_id, first_order_market, cohort_month,
      COUNT(*)                               AS customers,
      COUNTIF(costed)                        AS costed_customers,
      COUNTIF(n_30 >= 2)  AS rep_30,  COUNTIF(n_60 >= 2)  AS rep_60,  COUNTIF(n_90 >= 2) AS rep_90,
      COUNTIF(n_180 >= 2) AS rep_180, COUNTIF(n_365 >= 2) AS rep_365,
      SUM(rev_30) AS rev_30, SUM(rev_60) AS rev_60, SUM(rev_90) AS rev_90,
      SUM(rev_180) AS rev_180, SUM(rev_365) AS rev_365,
      SUM(IF(costed, gp_30, NULL))  AS gp_30,  SUM(IF(costed, gp_60, NULL))  AS gp_60,
      SUM(IF(costed, gp_90, NULL))  AS gp_90,  SUM(IF(costed, gp_180, NULL)) AS gp_180,
      SUM(IF(costed, gp_365, NULL)) AS gp_365,
      SUM(IF(costed, first_gp, NULL))        AS first_order_gp,
      SUM(first_revenue)                     AS first_order_revenue
    FROM per_cust
    GROUP BY client_id, first_order_market, cohort_month
  ),
  spend AS (
    SELECT client_id, market, DATE_TRUNC(date, MONTH) AS month, SUM(spend_base) AS spend
    FROM `oneeighty-warehouse.mart_qa.mk_market_spend_daily`
    GROUP BY 1, 2, 3
  ),
  spend_months AS (
    SELECT DISTINCT client_id, DATE_TRUNC(date, MONTH) AS month
    FROM `oneeighty-warehouse.mart_qa.mk_market_spend_daily`
  ),
  aged AS (
    SELECT c.*, a.as_of_date,
      LAST_DAY(c.cohort_month, MONTH) AS cohort_end
    FROM coh c JOIN as_of a USING (client_id)
  )
  SELECT
    g.client_id,
    g.first_order_market,
    g.cohort_month,
    g.customers,
    IF(DATE_ADD(g.cohort_end, INTERVAL 29 DAY)  <= g.as_of_date, g.rep_30,  NULL) AS repeat_customers_30,
    IF(DATE_ADD(g.cohort_end, INTERVAL 29 DAY)  <= g.as_of_date, g.rev_30,  NULL) AS revenue_30,
    IF(DATE_ADD(g.cohort_end, INTERVAL 29 DAY)  <= g.as_of_date, g.gp_30,   NULL) AS gp_30,
    IF(DATE_ADD(g.cohort_end, INTERVAL 59 DAY)  <= g.as_of_date, g.rep_60,  NULL) AS repeat_customers_60,
    IF(DATE_ADD(g.cohort_end, INTERVAL 59 DAY)  <= g.as_of_date, g.rev_60,  NULL) AS revenue_60,
    IF(DATE_ADD(g.cohort_end, INTERVAL 59 DAY)  <= g.as_of_date, g.gp_60,   NULL) AS gp_60,
    IF(DATE_ADD(g.cohort_end, INTERVAL 89 DAY)  <= g.as_of_date, g.rep_90,  NULL) AS repeat_customers_90,
    IF(DATE_ADD(g.cohort_end, INTERVAL 89 DAY)  <= g.as_of_date, g.rev_90,  NULL) AS revenue_90,
    IF(DATE_ADD(g.cohort_end, INTERVAL 89 DAY)  <= g.as_of_date, g.gp_90,   NULL) AS gp_90,
    IF(DATE_ADD(g.cohort_end, INTERVAL 179 DAY) <= g.as_of_date, g.rep_180, NULL) AS repeat_customers_180,
    IF(DATE_ADD(g.cohort_end, INTERVAL 179 DAY) <= g.as_of_date, g.rev_180, NULL) AS revenue_180,
    IF(DATE_ADD(g.cohort_end, INTERVAL 179 DAY) <= g.as_of_date, g.gp_180,  NULL) AS gp_180,
    IF(DATE_ADD(g.cohort_end, INTERVAL 364 DAY) <= g.as_of_date, g.rep_365, NULL) AS repeat_customers_365,
    IF(DATE_ADD(g.cohort_end, INTERVAL 364 DAY) <= g.as_of_date, g.rev_365, NULL) AS revenue_365,
    IF(DATE_ADD(g.cohort_end, INTERVAL 364 DAY) <= g.as_of_date, g.gp_365,  NULL) AS gp_365,
    IF(sm.client_id IS NULL, NULL, IFNULL(s.spend, 0))                            AS cohort_spend,
    g.first_order_gp,
    g.costed_customers,
    g.first_order_revenue,
    g.as_of_date
  FROM aged g
  LEFT JOIN spend s
    ON s.client_id = g.client_id AND s.market = g.first_order_market AND s.month = g.cohort_month
  LEFT JOIN spend_months sm
    ON sm.client_id = g.client_id AND sm.month = g.cohort_month;

  SET new_rows = (SELECT COUNT(*) FROM `oneeighty-warehouse.mart_qa.mk_market_cohorts__next`);
  SET dup_rows = (
    SELECT COUNT(*) - COUNT(DISTINCT FORMAT('%s|%s|%t', client_id, first_order_market, cohort_month))
    FROM `oneeighty-warehouse.mart_qa.mk_market_cohorts__next`);
  SET cust_gap = (
    SELECT ABS((SELECT SUM(customers) FROM `oneeighty-warehouse.mart_qa.mk_market_cohorts__next`)
             - (SELECT COUNTIF(is_new_customer) FROM `oneeighty-warehouse.mart_qa.mk_market_orders`)));

  ASSERT new_rows > 0 AS 'market_cohorts: new build is empty';
  ASSERT dup_rows = 0 AS 'market_cohorts: duplicate client_id + first_order_market + cohort_month';
  ASSERT cust_gap = 0 AS 'market_cohorts: customers differ from new customers in market_orders';

  CREATE OR REPLACE TABLE `oneeighty-warehouse.mart_qa.mk_market_cohorts`
  COPY `oneeighty-warehouse.mart_qa.mk_market_cohorts__next`;
  ALTER TABLE `oneeighty-warehouse.mart_qa.mk_market_cohorts`
  SET OPTIONS (description = 'Markets: monthly cohorts per client x first-order market with cumulative repeat customers, revenue and GP at 30/60/90/180/365 days (NULL until mature), cohort-month spend and first-order GP. GP per customer = gp_N / costed_customers. Built by mart.sp_refresh_market_cohorts (migration 293).');
  DROP TABLE `oneeighty-warehouse.mart_qa.mk_market_cohorts__next`;
END;

CALL `oneeighty-warehouse.mart_qa.mk_sp_refresh_market_cohorts`();
